contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 v) public {
        c.getTokens(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        require(v > 0 && v <= balBefore);
        c.burn(v); if (__ESBMC_reverted()) return;
        assert(
            c.balanceOf(address(this)) == balBefore - v &&
            c.totalSupply() == supplyBefore - v &&
            c.totalDistributed() == distBefore - v
        );
    }
    receive() external payable {}
}

